sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },
	isDatePast: function(strDate){
		gs.info("DEBUG DATE: Entra nella funzione isDatePast");
		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);
		if (testdate.before(rightnow)){
			return true;
		} else {
			return false;
		}
	},
	isSameDay: function(strDate){
		gs.info("DEBUG DATE: Entra nella funzione isSameDay");
		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);
		if(testdate.getDate().getValue() == rightnow.getDate().getValue()){
			return true;
		} else {
			return false;
		}
	},
    type: 'NeedItUtils'
};
